From 73dda5d3ac984a36303dfb2812d87bc3ce89513d Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 03:02:39 +0100
Subject: [PATCH] applets/batterymonitor: don't blame the charger above the
 charge limit

Some laptops let the battery discharge while plugged in when it is above
its charge limit, and the tooltip then wrongly said the power supply was
too weak. In that case we now show the configured charge limit instead.

BUG: 491731
---
 applets/batterymonitor/main.qml | 7 ++++++-
 1 file changed, 6 insertions(+), 1 deletion(-)

diff --git a/applets/batterymonitor/main.qml b/applets/batterymonitor/main.qml
index 7999bddb3..2e4826fb8 100644
--- a/applets/batterymonitor/main.qml
+++ b/applets/batterymonitor/main.qml
@@ -145,7 +145,12 @@ PlasmoidItem {

         // Add special text for the "plugged in but still discharging" case
         if (batteryControl.pluggedIn && batteryControl.state === BatteryControlModel.Discharging) {
-            parts.push(i18n("The power supply is not powerful enough to charge the battery"));
+            const threshold = batteryControl.chargeStopThreshold;
+            if (threshold > 0 && threshold < 100 && batteryControl.percent >= threshold) {
+                parts.push(i18n("Battery is configured to charge up to approximately %1%.", threshold));
+            } else {
+                parts.push(i18n("The power supply is not powerful enough to charge the battery"));
+            }
         }

         if (!batteryControl.hasBatteries) {
